  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,wt]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=(Math.sin(d*f-t*sp)+Math.sin(d*f*1.618-t*sp*0.7))*wt;
    iS+=(Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.cos(d*f*0.5-t*sp*0.4))*wt;
    hS+=Math.sin(d*f*0.3-t*sp*0.3+3.0)*wt;
  }
  const act=aS/10,inh=iS/10,harm=hS/10;
  const bg1=Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3;
  const bg3=Math.sin(sx*0.08+Math.sin(sy*0.05+t)*3+t*1.5)*0.4;
  const bg=(bg1+bg2+bg3)/2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*5-t*1.2)*0.7+Math.sin(dist*0.07-ang*2+t*0.8)*0.3)*0.35;
  const c1=Math.sin(sx*0.15)*Math.sin(sy*0.15),c2=Math.sin((sx+sy)*0.1+t)*Math.sin((sx-sy)*0.08-t*0.7);
