  const cell=(c1+c2*0.5+c3*0.3)/1.8;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+harm*0.2)*2.2);
  const crossR=Math.tanh((act*0.5+harm-inh*0.8+spiral*0.5)*1.8);
  const cellR=Math.tanh(cell*1.5)*0.3;
  const blend=reaction*0.55+crossR*0.2+cellR*0.25,v=blend*0.5+0.5;
  const sh=Math.sin(t*0.15)*0.5+0.5;
  const pal=[
    [5+sh*4,10+sh*6,48+sh*8],
    [10+sh*5,52+sh*8,92+sh*10],
    [16+sh*6,115+sh*12,128+sh*10],
    [42+sh*8,172+sh*10,152+sh*8],
    [175+sh*10,192+sh*8,62+sh*10],
    [212+sh*8,152+sh*10,58+sh*8],
    [198+sh*6,92+sh*8,72+sh*10],
    [158+sh*8,52+sh*6,88+sh*8],
    [88+sh*6,22+sh*4,68+sh*6],
    [5+sh*4,10+sh*6,48+sh*8]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(crossR)>0.7?1.1:1.0;
  const glow=Math.max(0,1.0-Math.abs(blend)*1.5)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0)
  ];
}
